import { randomId } from '../utils';
import type Frame from './Frame';

export default class FrameGroup {
    id: string;
    rootFrame: Frame;
    _frames: Frame[] = []

    constructor(rootFrame: Frame) {
        this.id = randomId()
        this.rootFrame = rootFrame;
    }

    addFrame(frame: Frame) {
        if (frame.group) {
            frame.group.removeFrame(frame);
        }
        this._frames.push(frame);
        frame.group = this;
    }

    removeFrame(frame: Frame) {
        if (frame.group !== this) {
            throw new Error("Frame not in group.");
        }

        const index = this._frames.indexOf(frame);
        if (index === -1) {
            throw new Error("Frame not found in group.");
        }
        this._frames.splice(index, 1);
        frame.group = null;
    }

    get frames(): readonly Frame[] {
        return this._frames;
    }

    get exitFrames() {
        // exit frames are frames inside this group that have children outside the group.
        const exitFrames = []

        for (const frame of this.frames) {
            let isExit = false;
            for (const child of frame.children) {
                if (child.group != this) {
                    isExit = true;
                    break;
                }
            }

            if (isExit) {
                exitFrames.push(frame);
            }
        }

        return exitFrames;
    }

    get libraries() {
        const libraries: string[] = [];

        for (const frame of this.frames) {
            const library = frame.library
            if (!library) {
                continue
            }

            if (!libraries.includes(library)) {
                libraries.push(library);
            }
        }

        return libraries;
    }
}

import type Frame from "./Frame"
import type { Processor, ProcessorFunction, ProcessorOptions } from "./processors"

export function applyProcessors(rootFrame: Frame | null, processors: ProcessorFunction[], options: ProcessorOptions) {
    let frame: Frame | null = rootFrame
    for (const processor of processors) {
        frame = processor(frame, options)
        if (!frame) {
            return null
        }
    }
    return frame
}

import type { SessionData } from "../dataTypes";
import Frame from "./Frame";

export default class Session {
    startTime: number;
    duration: number;
    minInterval: number;
    maxInterval: number;
    precision: number;
    sampleCount: number;
    target_description: string;
    cpuTime: number;
    rootFrame: Frame|null;
    sysPath: string;
    sysPrefixes: string[];

    constructor(data: SessionData) {
        this.startTime = data.session.start_time;
        this.duration = data.session.duration;
        this.minInterval = data.session.min_interval;
        this.maxInterval = data.session.max_interval;
        this.sampleCount = data.session.sample_count;
        this.target_description = data.session.target_description;
        this.cpuTime = data.session.cpu_time;
        this.sysPath = data.session.sys_path;
        this.sysPrefixes = data.session.sys_prefixes
        this.precision = Math.ceil(-Math.log10(Math.min(Math.max(1e-9, this.maxInterval), 1)))
        this.rootFrame = data.frame_tree ? new Frame(data.frame_tree, this) : null
    }

    _shortenPathCache: {[path: string]: string} = {}
    shortenPath(path: string): string {
        if (this._shortenPathCache[path]) {
            return this._shortenPathCache[path]
        }

        let result = path
        const pathParts = pathSplit(path)

        if (pathParts.length > 1) {
            for (const sysPathEntry of this.sysPath) {
                const candidate = getRelPath(path, sysPathEntry)
                if (pathSplit(candidate).length < pathSplit(result).length) {
                    result = candidate
                }
            }
        }

        this._shortenPathCache[path] = result
        return result
    }
}

function pathSplit(path: string): string[] {
    return path.split(/[/\\]/)
}

function getPathDrive(path: string): string | null {
    const parts = pathSplit(path)
    if (parts.length > 0 && parts[0].endsWith(":")) {
        return parts[0]
    } else {
        return null
    }
}

function getRelPath(path: string, start: string): string {
    // returns the relative path from start to path
    // e.g. getRelPath("/a/b/c", "/a") -> "b/c"
    // e.g. getRelPath("/a/b/c", "/a/d/e") -> "../../b/c"

    if (getPathDrive(path) != getPathDrive(start)) {
        // different drives, can't make a relative path
        return path
    }

    const parts = pathSplit(path)
    const startParts = pathSplit(start)
    let i = 0
    while (i < parts.length && i < startParts.length && parts[i] == startParts[i]) {
        i++
    }
    const relParts = startParts.slice(i).map(_ => "..")

    return relParts.concat(parts.slice(i)).join("/")
}

import { UnreachableCaseError } from "../utils";
import Frame from "./Frame";
import { SELF_TIME_FRAME_IDENTIFIER } from "./Frame";

export function deleteFrameFromTree(frame: Frame, options: {replaceWith: 'children'|'self_time'|'nothing'}) {
    const {replaceWith} = options
    const parent = frame.parent
    if (!parent) {
        throw new Error('Cannot delete the root frame')
    }

    if (replaceWith == 'children') {
        parent.addChildren(frame.children, {after: frame})
    } else if (replaceWith == 'self_time') {
        parent.addChild(
            new Frame({
                identifier: SELF_TIME_FRAME_IDENTIFIER,
                time: frame.time,
            }, parent.context),
            {after: frame}
        )
    } else if (replaceWith == 'nothing') {
        parent.absorbedTime += frame.time
    } else {
        throw new UnreachableCaseError(replaceWith)
    }

    frame.removeFromParent()
    removeFrameFromGroups(frame, true)
}

/**
 * Combines two frames into one. The frames must have the same parent.
 *
 * @param frame The frame to remove.
 * @param into The frame to combine into.
 */
export function combineFrames(frame: Frame, into: Frame): void {
    if (frame.parent !== into.parent) {
        throw new Error("Both frames must have the same parent.");
    }

    into.absorbedTime += frame.absorbedTime;
    into.time += frame.time;

    Object.entries(frame.attributes).forEach(([attribute, time]) => {
        if (into.attributes[attribute] !== undefined) {
            into.attributes[attribute] += time;
        } else {
            into.attributes[attribute] = time;
        }
    });

    into.addChildren(frame.children);
    frame.removeFromParent();
    removeFrameFromGroups(frame, false);
}

/**
 * Removes a frame from any groups that it is a member of. Should be used when
 * removing a frame from a tree, so groups don't keep references to removed frames.
 *
 * @param frame The frame to be removed from groups.
 * @param recursive Whether to also remove all child frames from their groups.
 */
export function removeFrameFromGroups(frame: Frame, recursive: boolean): void {
    if (recursive && frame.children) {
        frame.children.forEach(child => {
            removeFrameFromGroups(child, true);
        });
    }

    if (frame.group) {
        const group = frame.group;
        group.removeFrame(frame);

        if (group.frames.length === 1) {
            // A group with only one frame is meaningless; remove it entirely.
            group.removeFrame(group.frames[0]);
        }
    }
}

import type FrameGroup from './FrameGroup';
import { randomId } from '../utils';
// import type { FrameData } from '../dataTypes';

export interface FrameData {
    identifier: string,
    time?: number // duration in seconds
    startTime?: number
    attributes?: {[name: string]: number},
    children?: readonly FrameData[],
}


const IDENTIFIER_SEP = "\x00"
const ATTRIBUTES_SEP = "\x01"

export const AWAIT_FRAME_IDENTIFIER = "[await]"
export const SELF_TIME_FRAME_IDENTIFIER = "[self]"
export const OUT_OF_CONTEXT_FRAME_IDENTIFIER = "[out-of-context]"
export const DUMMY_ROOT_FRAME_IDENTIFIER = "[root]"

export const SYNTHETIC_FRAME_IDENTIFIERS = [
    AWAIT_FRAME_IDENTIFIER,
    SELF_TIME_FRAME_IDENTIFIER,
    OUT_OF_CONTEXT_FRAME_IDENTIFIER,
    DUMMY_ROOT_FRAME_IDENTIFIER,
]

export const SYNTHETIC_LEAF_IDENTIFIERS = [
    AWAIT_FRAME_IDENTIFIER,
    SELF_TIME_FRAME_IDENTIFIER,
    OUT_OF_CONTEXT_FRAME_IDENTIFIER,
]

const ATTRIBUTE_MARKER_CLASS_NAME = "c"
const ATTRIBUTE_MARKER_LINE_NUMBER = "l"
const ATTRIBUTE_MARKER_TRACEBACKHIDE = "h"

export default class Frame {
    uuid: string = randomId()
    identifier: string
    _identifierParts: string[]
    startTime: number
    time: number = 0
    absorbedTime: number = 0
    group: FrameGroup|null = null
    attributes: {[name: string]: number}
    _children: Frame[] = []
    parent: Frame | null = null

    context: FrameContext

    constructor(
        data: FrameData,
        context: FrameContext,
    ) {
        this.identifier = data.identifier
        this._identifierParts = this.identifier.split(IDENTIFIER_SEP)
        this.startTime = data.startTime ?? 0
        this.time = data.time ?? 0
        this.attributes = data.attributes ?? {}
        this.context = context

        let childStartTime = this.startTime
        const children = data.children?.map(f => {
            if (f.startTime === undefined) {
                f = {...f, startTime: childStartTime}
                childStartTime += f.time ?? 0
            }
            childStartTime = f.startTime! + (f.time ?? 0)
            return new Frame(f, context)
        });
        if (children) {
            this.addChildren(children)
        }
    }

    cloneDeep(): Frame {
        return new Frame(this, this.context)
    }

    get children(): readonly Frame[] {
        return this._children
    }

    addChild(frame: Frame, options: {after?: Frame} = {}) {
        frame.removeFromParent()
        frame.parent = this
        if (options.after) {
            const index = this._children.indexOf(options.after)
            if (index == -1) {
                throw new Error("After frame not found")
            }
            this._children.splice(index+1, 0, frame)
        } else {
            this._children.push(frame)
        }
    }

    addChildren(frames: readonly Frame[], options: {after?: Frame} = {}) {
        frames = frames.slice()
        if (options.after) {
            const reversed = frames.slice()
            reversed.reverse()
            frames.forEach(f => this.addChild(f, options))
        } else {
            frames.forEach(f => this.addChild(f, options))
        }
    }

    removeFromParent() {
        if (this.parent) {
            const idx = this.parent._children.indexOf(this)
            this.parent._children.splice(idx, 1)
            this.parent = null
        }
    }

    getAttributes(marker: string): {data: string, time: number}[] {
        const keys = Object.keys(this.attributes).filter(k => k.startsWith(marker))
        return keys.map(k => (
            {data: k.slice(1), time: this.attributes[k]}
        ))
    }

    getAttributeValue(marker: string) {
        const attributes = this.getAttributes(marker)
        if (!attributes) return null
        if (attributes.length == 0) return null

        let maxIdx = 0
        for (let i = 0; i < attributes.length; i++) {
            if (attributes[i].time > attributes[maxIdx].time) {
                maxIdx = i
            }
        }

        return attributes[maxIdx].data
    }

    get hasTracebackHide(): boolean {
        return this.getAttributeValue(ATTRIBUTE_MARKER_TRACEBACKHIDE) == '1'
    }

    get function(): string {
        return this._identifierParts[0]
    }

    get filePath(): string | null {
        return this._identifierParts[1] ?? null
    }

    get lineNo(): number | null {
        const lineNo = this._identifierParts[2]
        return lineNo ? parseInt(lineNo) : null
    }

    get isSynthetic(): boolean {
        return SYNTHETIC_FRAME_IDENTIFIERS.includes(this.identifier)
    }

    get filePathShort(): string | null {
        if (this.isSynthetic && this.parent) {
            return this.parent.filePathShort
        }

        if (!this.filePath) return null

        return this.context.shortenPath(this.filePath)
    }

    get isApplicationCode(): boolean {
        if (this.isSynthetic) {
            return false;
        }

        const filePath = this.filePath;

        if (!filePath) {
            return false;
        }

        const prefixes = this.context.sysPrefixes
        if (prefixes.some(path => filePath.startsWith(path))) {
            // this code lives in the Python installation dir or a virtualenv
            return false;
        }

        if (filePath.startsWith("<")) {
            if (filePath.startsWith("<ipython-input-")) {
                // Lines typed at a console or in a notebook are considered application code
                return true;
            } else if (filePath == "<string>" || filePath == "<stdin>") {
                // eval/exec is app code if started by a parent frame that is app code
                if (this.parent) {
                    return this.parent.isApplicationCode
                } else {
                    // if this is the root frame, it must have been started
                    // with -c, so it's app code
                    return true
                }
            } else {
                // Otherwise, this is likely some form of library-internal code generation
                return false;
            }
        }

        return true;
    }

    get proportionOfParent(): number {
        if (!this.parent) {
            return 1;
        }

        return this.time / this.parent.time;
    }

    get className(): string {
        return this.getAttributeValue(ATTRIBUTE_MARKER_CLASS_NAME) ?? ""
    }

    get library(): string|null {
        const filePathShort = this.filePathShort;
        if (!filePathShort) {
            return null;
        }
        // return the first part of the path that isn't slashes or dots
        return /^[\\/.]*[^\\/.]*/.exec(filePathShort)![0] ?? ''
    }
}

interface FrameContext {
    shortenPath(path: string): string
    sysPrefixes: string[]
    precision: number
}

import { maxBy } from "../utils";
import type Frame from "./Frame";
import { SELF_TIME_FRAME_IDENTIFIER } from "./Frame";
import FrameGroup from "./FrameGroup";
import { combineFrames, deleteFrameFromTree } from './frameOps'

export interface ProcessorOptions {
    filterThreshold?: number // used by remove_irrelevant_nodes
    hideRegex?: string // used by group_library_frames_processor
    showRegex?: string // used by group_library_frames_processor
}
export type ProcessorFunction = (frame: Frame | null, options: ProcessorOptions) => Frame | null

export interface Processor {
    name: string
    description: string
    function: ProcessorFunction
    optionsSpec: {
        key: string,
        name: string,
        value: {
            type: 'string',
            default: string
        } | {
            type: 'number',
            default: number
            min?: number
            max?: number
            sliderMin?: number
            sliderMax?: number
            sliderLogarithmic?: boolean
        } | {
            type: 'boolean',
            default: boolean
        }
    }[],
    category: 'normal' | 'advanced'
}

export const allProcessors: Processor[] = []

/**
 * Removes ``<frozen importlib._bootstrap`` frames that clutter the output.
 */
export function remove_importlib(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null
    }

    for (const child of frame.children) {
        remove_importlib(child, options)

        if (child.filePath && child.filePath.includes("<frozen importlib._bootstrap")) {
            deleteFrameFromTree(child, { replaceWith: "children" })
        }
    }

    return frame
}
allProcessors.push({
    name: "remove_importlib",
    description: "Removes <frozen importlib._bootstrap frames that clutter the output.",
    function: remove_importlib,
    optionsSpec: [],
    category: 'normal',
})

/**
 * Removes frames that have set a local `__traceback_hide__` (e.g.
 * `__traceback_hide__ = True`), to remove them from the output.
 */
export function remove_tracebackhide(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null
    }

    for (const child of frame.children) {
        remove_tracebackhide(child, options)

        if (child.hasTracebackHide) {
            deleteFrameFromTree(child, { replaceWith: "children" })
        }
    }

    return frame
}
allProcessors.push({
    name: "remove_tracebackhide",
    description: "Removes frames that have set a local __traceback_hide__ (e.g. __traceback_hide__ = True), to remove them from the output.",
    function: remove_tracebackhide,
    optionsSpec: [],
    category: 'advanced',
})

/**
 * Converts a timeline into a time-aggregate summary.
 *
 * Adds together calls along the same call stack, so that repeated calls
 * appear as the same frame. Removes time-linearity - frames are sorted
 * according to total time spent.
 *
 * Useful for outputs that display a summary of execution (e.g., text and HTML
 * outputs).
 */
export function aggregate_repeated_calls(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null;
    }

    const childrenByIdentifier: Record<string, Frame> = {};

    for (const child of frame.children.slice()) {
        if (childrenByIdentifier[child.identifier]) {
            const aggregateFrame = childrenByIdentifier[child.identifier];
            combineFrames(child, aggregateFrame);
        } else {
            childrenByIdentifier[child.identifier] = child;
        }
    }

    frame.children.forEach(child => aggregate_repeated_calls(child, options));
    frame._children.sort((a, b) => b.time - a.time);

    return frame;
}
allProcessors.push({
    name: "aggregate_repeated_calls",
    description: "Converts a timeline into a time-aggregate summary. Adds together calls along the same call stack, so that repeated calls appear as the same frame. Removes time-linearity - frames are sorted according to total time spent.",
    function: aggregate_repeated_calls,
    optionsSpec: [],
    category: 'normal',
})

/**
 * Groups frames that should be hidden into FrameGroup objects,
 * according to `remove_regex` and `show_regex` in the options dictionary.
 */
export function group_library_frames_processor(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null;
    }

    const hideRegex = options.hideRegex;
    const showRegex = options.showRegex;

    function shouldHide(frame: Frame): boolean {
        const filePath = frame.filePath || "";
        const show = showRegex && new RegExp(showRegex).test(filePath);
        const hide = hideRegex && new RegExp(hideRegex).test(filePath);

        if (show) {
            return false;
        }
        if (hide) {
            return true;
        }
        return !frame.isApplicationCode
    }

    function addFramesToGroup(frame: Frame, group: FrameGroup): void {
        group.addFrame(frame);
        frame.children.forEach(child => {
            if (shouldHide(child)) {
                addFramesToGroup(child, group);
            }
        });
    }

    frame.children.forEach(child => {
        if (!child.group && shouldHide(child) && child.children.some(shouldHide)) {
            const group = new FrameGroup(child);
            addFramesToGroup(child, group);
        }

        group_library_frames_processor(child, options);
    });

    return frame;
}
allProcessors.push({
    name: "Group library frames",
    description: "Groups frames that should be hidden.",
    function: group_library_frames_processor,
    optionsSpec: [
        {
            key: "hideRegex",
            name: "Hide regex",
            value: {
                type: "string",
                default: ""
            }
        },
        {
            key: "showRegex",
            name: "Show regex",
            value: {
                type: "string",
                default: ""
            }
        }
    ],
    category: 'normal',
})

/**
 * Combines consecutive 'self time' frames.
 */
export function merge_consecutive_self_time(frame: Frame | null, options: ProcessorOptions, recursive: boolean = true): Frame | null {
    if (!frame) {
        return null;
    }

    let previousSelfTimeFrame: Frame | null = null;

    for (const child of frame.children) {
        if (child.identifier === SELF_TIME_FRAME_IDENTIFIER) {
            if (previousSelfTimeFrame) {
                previousSelfTimeFrame.time += child.time;
                child.removeFromParent();
            } else {
                previousSelfTimeFrame = child;
            }
        } else {
            previousSelfTimeFrame = null;
        }
    }

    if (recursive) {
        frame.children.forEach(child => merge_consecutive_self_time(child, options, true));
    }

    return frame;
}
allProcessors.push({
    name: "Merge consecutive self time",
    description: "Combines consecutive 'self time' frames.",
    function: merge_consecutive_self_time,
    optionsSpec: [],
    category: 'advanced',
})

/**
 * Removes unnecessary self-time nodes.
 */
export function remove_unnecessary_self_time_nodes(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null;
    }

    if (frame.children.length === 1 && frame.children[0].identifier === SELF_TIME_FRAME_IDENTIFIER) {
        deleteFrameFromTree(frame.children[0], { replaceWith: "nothing" });
    }

    frame.children.forEach(child => remove_unnecessary_self_time_nodes(child, options));

    return frame;
}
allProcessors.push({
    name: "Remove unnecessary self time nodes",
    description: "Removes unnecessary self-time nodes.",
    function: remove_unnecessary_self_time_nodes,
    optionsSpec: [],
    category: 'advanced',
})

/**
 * Removes nodes that represent less than a certain percentage of the output.
 */
export function remove_irrelevant_nodes(frame: Frame | null, options: ProcessorOptions, totalTime: number | null = null): Frame | null {
    if (!frame) {
        return null;
    }

    if (totalTime === null) {
        totalTime = frame.time;
        if (totalTime <= 0) {
            totalTime = 1e-44;  // Prevent divide by zero
        }
    }

    const filterThreshold = options.filterThreshold ?? 0.01;

    for (const child of frame.children.slice()) {
        const proportionOfTotal = child.time / totalTime;
        if (proportionOfTotal < filterThreshold) {
            deleteFrameFromTree(child, { replaceWith: "nothing" });
        }
    }

    frame.children.forEach(child => remove_irrelevant_nodes(child, options, totalTime));

    return frame;
}
allProcessors.push({
    name: "Remove irrelevant nodes",
    description: "Removes nodes that represent less than a certain percentage of the output.",
    function: remove_irrelevant_nodes,
    optionsSpec: [
        {
            key: "filterThreshold",
            name: "Filter threshold",
            value: {
                type: "number",
                default: 0.01,
                min: 0,
                max: 1,
                sliderMin: 0.0001,
                sliderMax: 1
            }
        }
    ],
    category: 'normal',
})

/**
 * Removes the initial frames specific to the command line use of pyinstrument.
 */
export function remove_first_pyinstrument_frames_processor(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null;
    }

    const longestFrame = (frames: readonly Frame[]) => maxBy(frames, f => f.time)

    const isInitialPyinstrumentFrame = (f: Frame) =>
        f.filePath?.includes("pyinstrument/__main__.py") && f.children.length > 0;

    const isExecFrame = (f: Frame) =>
        f.proportionOfParent > 0.8 && f.filePath?.includes("<string>") && f.children.length > 0;

    const isRunpyFrame = (f: Frame) =>
        f.proportionOfParent > 0.8 && (new RegExp(".*runpy.py").test(f.filePath ?? '') || f.filePath?.includes("<frozen runpy>")) && f.children.length > 0;

    let result = frame;

    if (!isInitialPyinstrumentFrame(result)) return frame;

    result = longestFrame(result.children)!

    if (!isExecFrame(result)) return frame;

    result = longestFrame(result.children)!

    if (!isRunpyFrame(result)) return frame;

    while (isRunpyFrame(result)) {
        result = longestFrame(result.children)!
    }

    result.removeFromParent();

    return result;
}

export function remove_useless_groups_processor(frame: Frame | null, options: ProcessorOptions): Frame | null {
    if (!frame) {
        return null;
    }

    frame.children.forEach(child => remove_useless_groups_processor(child, options));

    // a group with only two frames is meaningless, you still print the root
    // frame, so you're just collapsing the single child frame with a group,
    // which is better printed as just a single frame
    if (frame.group && frame.group.frames.length < 3) {
        frame.group.removeFrame(frame);
    }

    return frame;
}

allProcessors.push({
    name: "Remove first pyinstrument frames",
    description: "Removes the initial frames specific to the command line use of pyinstrument.",
    function: remove_first_pyinstrument_frames_processor,
    optionsSpec: [],
    category: 'advanced',
})

